<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;mysql -u&quot;$MYSQL_USER&quot; -p&quot;$MYSQL_PASSWORD&quot; &quot;$MYSQL_DATABASE&quot; -e \\</span></span>
